from hera.analysis import open_run,sdh_onset,sdh_fft
import numpy as np
for i in (6,7):
 r=open_run(f'data/{i}');B=r.col('magnet_field');R=r.col('sr1_X')/1e-8
 print('\nRUN',i,'R range',np.min(R),np.median(R),np.max(R))
 try:
  o=sdh_onset(R,B,r_full_scale=5000)
  print(o.summary());print('onset_b',o.onset_b,'clip_high_b',o.clip_high_b)
