  try:
   f,s=sdh_fft(R[:,None],B,b_range=(lo,10),log=False,nfft=4096)
   from scipy.signal import find_peaks
   y=s[0];p,_=find_peaks(y,prominence=max(y)*0.08)
   pp=sorted(p,key=lambda j:y[j],reverse=True)[:8]
   print('fft',lo,[(round(f[j],2),round(y[j],2)) for j in pp])
  except Exception as e: print('FFT ERR',e)
